"""Rebuild reviewed, bilingual teaching material after editing example sources."""
import json
import re
from pathlib import Path

from line_notes import explain, pair

ROOT = Path(__file__).resolve().parent

# Title, mechanism, observed result, question, answer: authored for each exercise.
TOPICS = [
    ('Współbieżne oczekiwania|Concurrent waits', 'gather planuje trzy korutyny; await pozwala nakładać ich oczekiwania.|gather schedules three coroutines; await lets their waits overlap.', 'Koniec A po 1 s, C po 2 s, B po 4 s. Wyniki [1, 4, 2] zachowują kolejność wejścia.|A finishes after 1 s, C after 2 s, B after 4 s. Results [1, 4, 2] preserve input order.', 'Ile trwałby wariant sekwencyjny?|How long would sequential execution take?', 'Około 7 s: 1 + 4 + 2. Współbieżnie około 4 s, plus narzut.|About 7 s: 1 + 4 + 2. Concurrently about 4 s plus overhead.'),
    ('Pierwszy serwer HTML|First HTML server', 'Handler to funkcja otrzymująca request i zwracająca odpowiedź. Router wybiera handler.|A handler receives a request and returns a response. The router chooses it.', 'GET / zwraca 200 i nagłówek HTML. Content-Type to text/html.|GET / returns 200 and an HTML heading. Content-Type is text/html.', 'Co zmienia content_type?|What does content_type change?', 'Mówi klientowi, jak interpretować body: tutaj jako HTML.|It tells the client how to interpret the body: HTML here.'),
    ('Parametr ścieżki|Path parameter', 'Fragment {name} w trasie przechwytuje tekst z URL do match_info.|The {name} route placeholder captures URL text into match_info.', '/witaj/Anna → Hello, Anna! Parametr zmienia treść odpowiedzi.|/witaj/Anna → Hello, Anna! The parameter changes the response.', 'Czy name pochodzi z JSON?|Does name come from JSON?', 'Nie, pochodzi ze ścieżki URL, z request.match_info.|No, it comes from the URL path through request.match_info.'),
    ('Odpowiedź JSON i czas|JSON response and time', 'Słownik Pythona staje się JSON przez web.json_response. Datę najpierw zamieniamy na tekst.|web.json_response converts a Python dictionary to JSON. Convert the date to text first.', 'GET /api/status zwraca status OK i lokalny czas jako tekst ISO.|GET /api/status returns status OK and local time as ISO text.', 'Dlaczego nie przekazać datetime bez konwersji?|Why not pass datetime directly?', 'Domyślny encoder JSON nie obsługuje obiektów datetime; isoformat daje tekst.|The default JSON encoder cannot serialize datetime objects; isoformat returns text.'),
    ('Query string i brak parametru|Query string and missing input', 'Query to parametry po znaku ?; get pozwala rozpoznać brak klucza.|Query parameters follow ?; get lets us detect a missing key.', '?q=python → 200 z frazą; brak q → 400. Pusty q jest obecnym parametrem.|?q=python → 200 with the phrase; absent q → 400. An empty q is still present.', 'Czym różni się brak q od ?q=?|How does absent q differ from ?q=?', 'Brak daje None, a obecny pusty parametr daje pusty tekst.|Absence gives None; a present empty parameter gives an empty string.'),
    ('POST i echo JSON|POST and JSON echo', 'Body to osobna część requestu. await request.json odbiera je i parsuje.|The body is a separate part of a request. await request.json reads and parses it.', 'POST z message: Python zwraca tę samą strukturę JSON.|POST with message: Python returns the same JSON structure.', 'Co się stanie przy uszkodzonym JSON?|What happens with malformed JSON?', 'JSONDecodeError trafia do except i odpowiedzi 400.|JSONDecodeError is caught and becomes a 400 response.'),
    ('Model Product i tabela|Product model and table', 'DeclarativeBase rejestruje modele; Mapped opisuje typy, a mapped_column kolumny SQL.|DeclarativeBase registers models; Mapped describes types and mapped_column SQL columns.', 'PostgreSQL tworzy tabelę products z id, name, price. Cena ma jednostkę groszy.|PostgreSQL creates products with id, name and price. Price uses cents.', 'Dlaczego price jest Integer?|Why is price Integer?', '1299 groszy reprezentuje 12,99 zł bez błędów zaokrągleń float.|1299 cents represents 12.99 without float rounding errors.'),
    ('Wyjątek jako odpowiedź 403|Exception as a 403 response', 'HTTPForbidden przerywa handler; aiohttp zamienia wyjątek na odpowiedź HTTP.|HTTPForbidden interrupts the handler; aiohttp converts it into an HTTP response.', 'Anna otrzymuje 200; admin otrzymuje 403 i nie dochodzi do powitania.|Anna receives 200; admin receives 403 without reaching the greeting.', 'Czy po raise wykona się return powitania?|Will the greeting return run after raise?', 'Nie. Wyjątek przerywa ten przebieg handlera.|No. The exception interrupts that execution of the handler.'),
    ('Tworzenie produktu|Create a product', 'add rejestruje obiekt, flush wykonuje INSERT, a poprawne wyjście z begin zatwierdza transakcję.|add tracks an object, flush executes INSERT, and normal exit from begin commits.', 'POST zapisuje Notebook za 1299 groszy; odpowiedź 201 ma wygenerowane id=1.|POST saves Notebook for 1299 cents; response 201 includes generated id=1.', 'Czy flush oznacza trwałe zatwierdzenie?|Does flush mean durable commit?', 'Nie. Zapis SQL nadal można wycofać; zatwierdzenie następuje przy wyjściu z begin.|No. The SQL write can still roll back; commit happens on exiting begin.'),
    ('Lista produktów|List products', 'select buduje zapytanie, execute je wykonuje, scalars wyciąga modele z wierszy.|select builds a query, execute runs it, and scalars extracts model objects from rows.', 'Po POST następuje GET /products: JSON jest listą z zapisanym Notebook.|After POST, GET /products returns a JSON list containing the saved Notebook.', 'Czy select sam odpytuje bazę?|Does select query the database by itself?', 'Nie. To opis zapytania; I/O zaczyna się przy execute.|No. It describes the query; I/O starts at execute.'),
    ('Produkt po ID i 404|Product by ID and 404', 'get pobiera rekord po kluczu głównym. None to brak wyniku, który obsługujemy jawnie.|get retrieves by primary key. None means absence and is handled explicitly.', '/products/1 daje 200; /products/999 daje 404.|/products/1 gives 200; /products/999 gives 404.', 'Dlaczego sprawdzamy None przed to_dict?|Why check None before to_dict?', 'None nie ma metody to_dict. Jawna kontrola daje poprawne 404 zamiast błędu serwera.|None has no to_dict method. An explicit check gives 404 instead of a server error.'),
    ('Klient publicznego API|Public API client', 'ClientSession jest klientem HTTP, a nie serwerem ani sesją bazy danych.|ClientSession is an HTTP client, not a server or database session.', 'Prawdziwe publiczne API zwraca bieżącą cenę BTC w USD. Wartość zależy od momentu zapytania.|A real public API returns the live BTC price in USD. Its value depends on request time.', 'Gdzie jest cena w słowniku?|Where is the price in the dictionary?', 'data["data"]["amount"]. Zewnętrzne data to zmienna; wewnętrzne "data" to klucz JSON.|data["data"]["amount"]. Outer data is a variable; inner "data" is a JSON key.'),
    ('Trzy żądania przez gather|Three requests with gather', 'Wspólna ClientSession obsługuje kilka połączeń. gather nakłada oczekiwania sieciowe.|A shared ClientSession handles several connections. gather overlaps network waits.', 'Odczytujemy BTC, ETH i LTC. Tory pokazują nakładanie żądań; lista wyników zachowuje kolejność URL.|Read BTC, ETH and LTC. Lanes show overlapping requests; results preserve URL order.', 'Czy AsyncSession bazy też można tak współdzielić?|Can a database AsyncSession also be shared this way?', 'Nie. Każde współbieżne zadanie powinno mieć własną sesję bazy.|No. Each concurrent task should have its own database session.'),
    ('Częściowa aktualizacja PATCH|Partial PATCH update', 'PATCH zmienia tylko przesłane pola. ORM śledzi zmiany atrybutów i zapisuje je w transakcji.|PATCH changes only submitted fields. The ORM tracks attributes and saves them in a transaction.', 'Cena Notebook zmienia się z 1299 na 999; GET potwierdza zapis. Nazwa pozostaje Notebook.|Notebook price changes from 1299 to 999; GET confirms the write. Its name stays Notebook.', 'Czy price=0 powinno być pominięte?|Should price=0 be skipped?', 'Nie. Sprawdzamy obecność klucza, a nie prawdziwość wartości.|No. Check whether the key exists, rather than whether its value is truthy.'),
    ('Usuwanie DELETE|DELETE operation', 'Usunięcie należy do transakcji. Po zatwierdzeniu zwracamy 204 bez body.|Deletion belongs to a transaction. After commit return 204 without a body.', 'DELETE /products/1 → 204; następny GET tego samego ID → 404.|DELETE /products/1 → 204; the next GET for the same ID → 404.', 'Czy klient powinien wywołać json na 204?|Should the client call json on a 204?', 'Nie. Odpowiedź nie zawiera treści JSON.|No. The response contains no JSON body.'),
    ('Przelew, blokady i rollback|Transfer, locks and rollback', 'Jedna transakcja obejmuje oba salda i historię. FOR UPDATE chroni wiersze przed równoległą zmianą.|One transaction covers both balances and history. FOR UPDATE protects rows against concurrent changes.', '100 groszy: salda 900 i 600. Próba 13 po flush kończy się 409; salda nadal 900 i 600. 9999 również daje 409.|100 cents gives balances 900 and 600. A 13-cent attempt fails after flush with 409; balances remain 900 and 600. 9999 also gives 409.', 'Po co awaria po flush, zamiast przed zmianą?|Why fail after flush instead of before the change?', 'Pokazuje, że rollback wycofuje SQL już wykonany w bazie, nie tylko obiekty w pamięci.|It demonstrates rollback of SQL already executed in the database, not just in-memory objects.'),
    ('Paginacja i stabilna kolejność|Pagination and stable ordering', 'page i limit określają okno danych. offset liczy pominięte rekordy; order_by stabilizuje kolejność.|page and limit define a data window. offset counts skipped rows; order_by stabilizes ordering.', 'Po dodaniu Notebook i Pen strona 2 z limitem 1 zwraca Pen. Strona 0 daje 400.|After adding Notebook and Pen, page 2 with limit 1 returns Pen. Page 0 gives 400.', 'Ile wynosi offset dla page=3 i limit=10?|What is the offset for page=3 and limit=10?', '(3 - 1) × 10 = 20; pomijamy pierwszych 20 rekordów.|(3 - 1) × 10 = 20; skip the first 20 records.'),
    ('Czat nie blokuje statusu|Chat does not block status', 'Handler czatu czeka przez asyncio.sleep, a pętla może w tym czasie obsłużyć inną trasę.|The chat handler waits using asyncio.sleep while the loop serves another route.', 'Status OK pojawia się przed odpowiedzią czatu, mimo że czat wystartował pierwszy.|Status OK appears before the chat response even though chat started first.', 'Co zmieni time.sleep(3)?|What would time.sleep(3) change?', 'Zablokuje wątek event loop i opóźni również odpowiedź statusu.|It blocks the event-loop thread and delays the status response too.'),
    ('Trasy w osobnym module|Routes in a separate module', 'setup_routes oddziela rejestrację adresów od handlerów i przygotowania aplikacji.|setup_routes separates URL registration from handlers and application setup.', 'Te same POST i GET działają po przeniesieniu rejestracji do routes.py.|The same POST and GET work after moving registration to routes.py.', 'Dlaczego przekazujemy funkcje jako argumenty?|Why pass functions as arguments?', 'routes.py nie musi importować task19, więc unikamy cyklicznych importów.|routes.py need not import task19, avoiding circular imports.'),
    ('JOIN produktu i twórcy|JOIN product and creator', 'Klucz obcy user_id łączy tabele. Jeden SELECT z JOIN pobiera produkt i użytkownika.|The user_id foreign key links tables. One SELECT with JOIN retrieves product and user.', '/products/1 zwraca Notebook i creator: Anna. Brak produktu daje 404.|/products/1 returns Notebook and creator: Anna. An absent product gives 404.', 'Co zawiera wiersz z select(Product, User)?|What does a row from select(Product, User) contain?', 'Dwa obiekty w kolejności SELECT: Product, potem User.|Two objects in SELECT order: Product, then User.'),
]


def bilingual(text):
    return dict(zip(('pl', 'en'), text.split('|', 1)))


def build():
    records=[]
    for number, topic in enumerate(TOPICS, 1):
        title,intro,takeaway,question,answer = map(bilingual,topic)
        source=(ROOT/'examples'/f'task{number:02}.py').read_text(encoding='utf-8')
        steps=[]
        context='moduł / module'
        for index,line in enumerate(source.splitlines(),1):
            if not line.strip():
                continue
            if line.startswith(('async def ', 'def ', 'class ')):
                context=line.split('(')[0].replace('async def ','').replace('def ','').replace('class ','')
            elif line.startswith('if __name__'):
                context='start → launch → asyncio.run → main'
            body=explain(line)
            steps.append(dict(id=f'line-{index}',name=f'L{index} · {context}',start=index,end=index,details=[],body=body))
        entry=next(i for i,s in enumerate(steps) if s['name'].endswith('start → launch → asyncio.run → main'))
        # Read the entry point first, then return to the file in source order.
        steps=steps[entry:]+steps[:entry]
        main_line=next(i for i,line in enumerate(source.splitlines(),1) if line.startswith('async def main'))
        if number == 1:
            flow=pair('Czytaj przebieg: __main__ → launch → asyncio.run → main → gather → trzy operation → sleep → return → lista wyników → metric. Definicje na górze pliku przygotowują funkcje; samo ich przeczytanie przez interpreter nie uruchamia oczekiwań.', 'Trace: __main__ → launch → asyncio.run → main → gather → three operation calls → sleep → return → result list → metric. Definitions prepare functions; reading them does not start the waits.')
        elif number in (12,13):
            flow=pair('Czytaj przebieg: __main__ → asyncio.run(main()) → ClientSession → GET publicznego API → status HTTP → response.json → słownik → metric. W zadaniu 13 gather uruchamia trzy fetch współbieżnie. Te pliki są klientami; nie uruchamiają własnego serwera.', 'Trace: __main__ → asyncio.run(main()) → ClientSession → public API GET → HTTP status → response.json → dictionary → metric. In task 13 gather runs three fetch calls concurrently. These files are clients; they do not start a server.')
        elif number == 7:
            flow=pair('Przy ładowaniu pliku SQLAlchemy rejestruje Base i Product. Potem __main__ → asyncio.run(main()) → database(Base) → utworzenie tabel → odczyt definicji kolumn → metric → usunięcie schematu pokazu. W tym zadaniu nie ma jeszcze handlera HTTP.', 'SQLAlchemy registers Base and Product when the module loads. Then __main__ → asyncio.run(main()) → database(Base) → table creation → column definition inspection → metric → demo schema removal. This exercise has no HTTP handler yet.')
        else:
            flow=pair('Czytaj przebieg: __main__ → launch → asyncio.run(main()) → przygotowanie aplikacji i tras → demo → klient HTTP → router → handler → odpowiedź → dziennik klienta. W zadaniach z bazą database(Base) przygotowuje fabrykę; handler tworzy własną sesję. Definicja handlera pojawia się wcześniej w pliku, ale jego ciało rusza dopiero po żądaniu. W zadaniu 18 main sam wysyła dwa żądania, aby pokazać ich nakładanie.', 'Trace: __main__ → launch → asyncio.run(main()) → application and routes → demo → HTTP client → router → handler → response → client log. In database tasks database(Base) prepares the factory; each handler creates its own session. A handler is defined earlier in the file but its body runs only after a request. In task 18 main sends two requests itself to show overlap.')
        steps.insert(0,dict(id='flow',name='Mapa wykonania / Execution map',start=main_line,end=main_line,details=[],body=flow))
        caveat=pair('Każdy pokaz jest osobnym procesem. Schemat bazy jest tymczasowy i usuwany po normalnym zakończeniu; wymuszone przerwanie może pozostawić schemat demo_. Dane lekcji 19 i 28 nie są używane. Zadania 12–13 wymagają internetu i mogą zgłosić błąd sieci zamiast wyniku.', 'Each demo is a separate process. Its temporary database schema is removed on normal completion; forced termination may leave a demo_ schema. Lesson 19 and 28 data are not used. Tasks 12–13 require internet and may report a network error instead of a result.')
        adaptation=pair('Kod i komunikaty są po angielsku. Serwery uruchamiają się na wolnym porcie i są sprawdzane prawdziwym klientem HTTP. Każdy plik zawiera własne rozwiązanie; api_support przygotowuje pokaz. Zadania 12–13 używają publicznego Coinbase zamiast starych adresów; zadanie 14 używa PATCH. Schemat PostgreSQL jest odtwarzany przy każdym pokazie.', 'Code and messages use English. Servers start on an available port and are exercised by a real HTTP client. Each file contains its own solution; api_support prepares the demo. Tasks 12–13 use public Coinbase endpoints instead of old URLs; task 14 uses PATCH. The PostgreSQL schema is recreated for each demo.')
        records.append(dict(number=number,title=title,intro=intro,takeaway=takeaway,question=question,answer=answer,
                            watch=pair('Przewidź kolejność zdarzeń, statusy i wartości, potem uruchom pokaz. '+takeaway['pl'], 'Predict event order, statuses and values, then run the demo. '+takeaway['en']),
                            caveat=caveat,extra_question=pair('Zmień jedną wartość wejściową w pliku. Która linia jako pierwsza zachowa się inaczej i dlaczego?', 'Change one input value in the file. Which line behaves differently first, and why?'),
                            extra_answer=pair('Zacznij od danych w main, prześledź wybrany handler i warunki. Wskaż konkretną zmianę wartości, statusu lub zapytania. Następnie uruchom ponownie i porównaj z przewidywaniem.', 'Start at the data in main and trace the chosen handler and conditions. Identify the changed value, status or query. Rerun and compare with your prediction.'),
                            presets=[dict(label='Pełny pokaz / Full demonstration',value={})], adaptation=adaptation,
                            steps=dict(file=f'task{number:02}.py',source=source,steps=steps),
                            terms=[dict(name='Mechanizm / Mechanism',body=intro),dict(name='Dane → działanie → wynik / Input → work → result',body=takeaway)]))
        folder=ROOT/'explanations'
        folder.mkdir(exist_ok=True)
        document=[f'# Zadanie {number:02}: {title["pl"]}', '', intro['pl'], '',
                  '## Przebieg', '', 'Start: blok `__main__` → `launch` → `asyncio.run(main())` → przygotowanie aplikacji → pokaz HTTP → router → handler → odpowiedź. Definicje funkcji i modeli są przygotowane przy ładowaniu modułu; ich ciała nie wykonują się wtedy.', '',
                  takeaway['pl'], '', '## Pełny kod', '', '```python',source.rstrip(),'```','', '## Linijka po linijce','']
        for step in sorted(steps,key=lambda s:s['start']):
            document.extend([f'### L{step["start"]}', '', '```python',source.splitlines()[step['start']-1],'```', '', step['body']['pl'],''])
        document.extend(['## Sprawdź rozumienie','', question['pl'],'', '<details><summary>Odpowiedź</summary>','',answer['pl'],'','</details>',''])
        (folder/f'task{number:02}.md').write_text('\n'.join(document),encoding='utf-8')
    (ROOT/'material.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'{len(records)} tasks; {sum(len(r["steps"]["steps"]) for r in records)} line explanations')


if __name__ == '__main__':
    build()
